<?php
namespace App\Services\Tournament;
use App\Models\{Registration,Tournament,User};
use Illuminate\Validation\ValidationException;
class RegistrationService { public function register(Tournament $tournament,User $player): Registration { if(!$player->isPlayer()) throw ValidationException::withMessages(['user'=>'Only players can register.']); if(!$tournament->registrationsOpen()) throw ValidationException::withMessages(['tournament'=>'Registrations are closed for this tournament.']); if($tournament->registrations()->where('player_id',$player->id)->exists()) throw ValidationException::withMessages(['registration'=>'You are already registered.']); if($tournament->max_players && $tournament->confirmedRegistrations()->count() >= $tournament->max_players) throw ValidationException::withMessages(['tournament'=>'This tournament is full.']); return Registration::create(['tournament_id'=>$tournament->id,'player_id'=>$player->id,'status'=>'confirmed','registered_at'=>now()]);} public function updateStatus(Registration $registration,$status): Registration {$registration->update(['status'=>$status]);return $registration->refresh();} public function cancel(Registration $registration): void {$registration->update(['status'=>'cancelled']);} }
